"""The schedule a retrying client would follow. See task.md."""

from __future__ import annotations

# A recorded response: {"status": int, "retry_after_ms": int}  (the second key
# is optional).
Response = dict

# A planned attempt: {"number": int, "start_ms": int, "delay_ms": int}.
Attempt = dict


class PolicyError(ValueError):
    """Raised for a policy or deadline that cannot describe a schedule."""


RETRYABLE = {429, 503, 500, 502}


def _validate(policy: dict, deadline_ms: int) -> None:
    base_ms = policy["base_ms"]
    factor = policy["factor"]
    max_attempts = policy["max_attempts"]

    if base_ms <= 0:
        raise PolicyError("base_ms must be strictly positive")

    if isinstance(factor, list):
        num, den = factor
        if den <= 0 or num < den:
            raise PolicyError("factor ratio must be >= 1")
    else:
        if factor < 1:
            raise PolicyError("factor must be >= 1")

    if max_attempts < 1:
        raise PolicyError("max_attempts must be >= 1")

    if deadline_ms < 0:
        raise PolicyError("deadline_ms must be non-negative")


def _computed_delay(base_ms: int, factor, max_delay_ms: int, n: int) -> int:
    k = n - 2
    if isinstance(factor, list):
        num, den = factor
        raw_num = base_ms * num**k
        raw_den = den**k
        backed = raw_num // raw_den
    else:
        backed = base_ms * factor**k
    return min(backed, max_delay_ms)


def plan(policy: dict, responses: list[Response], deadline_ms: int) -> list[Attempt]:
    """Return the attempts a client under `policy` would make against `responses`."""
    _validate(policy, deadline_ms)

    base_ms = policy["base_ms"]
    factor = policy["factor"]
    max_delay_ms = policy["max_delay_ms"]
    max_attempts = policy["max_attempts"]

    attempts: list[Attempt] = []
    start_ms = 0
    next_delay = 0
    n = 1

    while True:
        if n > max_attempts:
            break
        if n - 1 >= len(responses):
            break
        if n >= 2:
            start_ms += next_delay
        if start_ms >= deadline_ms:
            break

        attempts.append({"number": n, "start_ms": start_ms, "delay_ms": next_delay})

        response = responses[n - 1]
        status = response["status"]

        if status not in RETRYABLE:
            break

        if "retry_after_ms" in response:
            next_delay = response["retry_after_ms"]
        else:
            next_delay = _computed_delay(base_ms, factor, max_delay_ms, n + 1)

        n += 1

    return attempts
